<script setup>
import { computed, onMounted, onUnmounted, ref } from 'vue';
import { application } from '../presentation/application/presentation-runtime.js';
import { clearFormDraft, hasFormDraft } from '../../js/ui/form-drafts.js';
import { timelineArea } from '../../js/ui/timeline.js';
const props=defineProps({mode:{type:String,default:'CREATE'},record:{type:Object,default:null},authoritativeOdometer:{type:[Number,String],default:null}});
const emit=defineEmits(['close','saved']);
const formRef=ref(null),busy=ref(false),error=ref(''),success=ref(''),gpsStatus=ref('Waiting for location…'),lastPosition=ref(null),latestFuel=ref(null),editingLatest=ref(null),loadingLatest=ref(false);
const draft=ref({odometer:'',pricePerKg:'',amount:'',recordedAt:new Date().toISOString(),locationName:'',locationArea:null});
let watchId=null,reverseTimer=null;
const isEdit=computed(()=>props.mode==='EDIT'||!!editingLatest.value); const activeRecord=computed(()=>editingLatest.value||props.record||null); const title=computed(()=>isEdit.value?'Correct Fuel':'Quick Fuel');
const quantityKg=computed(()=>{const a=Number(draft.value.amount),p=Number(draft.value.pricePerKg);return Number.isFinite(a)&&a>0&&Number.isFinite(p)&&p>0?a/p:null});
const loadingLatestQuantity=computed(()=>{const r=latestFuel.value;if(!r)return null;if(r.quantity_kg!=null)return Number(r.quantity_kg);const a=Number(r.amount_paise),p=Number(r.price_per_kg);return Number.isFinite(a)&&Number.isFinite(p)&&p>0?a/100/p:null});
const timestampLabel=computed(()=>{const d=new Date(draft.value.recordedAt);return Number.isFinite(d.getTime())?d.toLocaleString():'Time unavailable'}); const latestTimestampLabel=computed(()=>{const d=new Date(latestFuel.value?.recorded_at||latestFuel.value?.created_at||'');return Number.isFinite(d.getTime())?d.toLocaleString():'Time unavailable'}); const locationLabel=computed(()=>draft.value.locationName||'Location unavailable'); const authoritative=computed(()=>props.authoritativeOdometer==null||props.authoritativeOdometer===''?null:Number(props.authoritativeOdometer)); const draftKey=computed(()=>isEdit.value?`fuel:edit:${activeRecord.value?.entityId||activeRecord.value?.id||'unknown'}`:'fuel:create');
function localIso(){return new Date().toISOString()}
function loadRecord(r){const record=r||{};draft.value={odometer:record.odometer??'',pricePerKg:record.pricePerKg??record.price_per_kg??'',amount:record.amount??(record.amount_paise!=null?Number(record.amount_paise)/100:''),recordedAt:record.occurredAt||record.recorded_at||record.date||localIso(),locationName:record.locationName??record.location_name??'',locationArea:record.locationArea??record.location_area??null}}
function fromRecord(){if(isEdit.value)loadRecord(activeRecord.value);else draft.value={odometer:'',pricePerKg:'',amount:'',recordedAt:localIso(),locationName:'',locationArea:null}}
async function loadLatestFuel(){if(isEdit.value)return;loadingLatest.value=true;try{const rows=await application.listFuel();const ordered=(Array.isArray(rows)?rows:[]).filter(r=>!r.is_deleted).sort((a,b)=>String(b.recorded_at||b.created_at||'').localeCompare(String(a.recorded_at||a.created_at||'')));latestFuel.value=ordered[0]||null}catch{latestFuel.value=null}finally{loadingLatest.value=false}}
function startEditLatest(){if(!latestFuel.value||busy.value)return;editingLatest.value=latestFuel.value;loadRecord(latestFuel.value);error.value='';success.value=''}
function reverseGeocode(position){clearTimeout(reverseTimer);reverseTimer=setTimeout(async()=>{const {latitude,longitude}=position.coords;try{const response=await fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${encodeURIComponent(latitude)}&lon=${encodeURIComponent(longitude)}`,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error();const data=await response.json();const a=data.address||{};const name=data.display_name||[a.suburb,a.city_district,a.city,a.town,a.village].filter(Boolean).join(', ')||null;draft.value.locationName=name||'';draft.value.locationArea=timelineArea({locationName:name,locationArea:null});gpsStatus.value=name?`Location captured · ${name}`:`Location captured · ${latitude.toFixed(5)}, ${longitude.toFixed(5)}`}catch{gpsStatus.value=`Location captured · ${latitude.toFixed(5)}, ${longitude.toFixed(5)}`}},100)}
function onPosition(position){lastPosition.value=position;gpsStatus.value='Location captured';reverseGeocode(position)}
function startLocation(){if(!navigator.geolocation){gpsStatus.value='Location unavailable on this device/browser';return}gpsStatus.value='Requesting location…';watchId=navigator.geolocation.watchPosition(onPosition,()=>{gpsStatus.value='Location permission unavailable'},{enableHighAccuracy:false,maximumAge:30000,timeout:1500});navigator.geolocation.getCurrentPosition(onPosition,()=>{}, {enableHighAccuracy:false,maximumAge:30000,timeout:1500})}
function stopLocation(){if(watchId!==null&&navigator.geolocation)navigator.geolocation.clearWatch(watchId);watchId=null;clearTimeout(reverseTimer)}
function validate(){const o=Number(draft.value.odometer),p=Number(draft.value.pricePerKg),a=Number(draft.value.amount);if(!Number.isInteger(o)||o<0)return'Enter a valid odometer.';if(!isEdit.value&&authoritative.value!=null&&o<authoritative.value)return'Fuel odometer cannot be below the authoritative odometer.';if(!Number.isFinite(p)||p<=0)return'Enter a valid price per kg.';if(!Number.isFinite(a)||a<=0)return'Enter a valid amount.';return''}
async function save(){if(busy.value)return;error.value='';const v=validate();if(v){error.value=v;return}busy.value=true;try{let result;const recordedAt=localIso();draft.value.recordedAt=recordedAt;const p=lastPosition.value;if(isEdit.value){result=await application.saveHistoricalCorrection({entityType:'Fuel',entityId:activeRecord.value?.entityId||activeRecord.value?.id},{recordedAt,odometer:Number(draft.value.odometer),pricePerKg:Number(draft.value.pricePerKg),amount:Number(draft.value.amount),locationName:draft.value.locationName||null,locationArea:draft.value.locationArea||null});success.value='Fuel record updated successfully.'}else{result=await application.recordFuel({odometer:Number(draft.value.odometer),price_per_kg:Number(draft.value.pricePerKg),amount_paise:Math.round(Number(draft.value.amount)*100),recorded_at:recordedAt,date:recordedAt.slice(0,10),scope:'BUSINESS',entry_source:'FUEL',latitude:p?.coords?.latitude??null,longitude:p?.coords?.longitude??null,location_name:draft.value.locationName||null,location_area:draft.value.locationArea||null});success.value='Fuel record saved successfully.'}clearFormDraft(formRef.value);emit('saved',result);emit('close')}catch(e){error.value=String(e?.message||e)}finally{busy.value=false}}
function cancel(){if(busy.value)return;if(formRef.value&&hasFormDraft(formRef.value)){const ok=globalThis.confirm?.('Discard this unsaved draft?');if(ok===false)return}clearFormDraft(formRef.value);emit('close')}
function closeOverlay(){if(busy.value)return;const ok=globalThis.confirm?.('Close Quick Fuel? Any unsaved entries will be lost.');if(ok===false)return;clearFormDraft(formRef.value);emit('close')}
function onKey(event){if(event.key==='Escape')closeOverlay()}
fromRecord();
onMounted(()=>{window.addEventListener('keydown',onKey);if(!isEdit.value){loadLatestFuel();startLocation()}}); onUnmounted(()=>{window.removeEventListener('keydown',onKey);stopLocation()});
</script>
<template>
<div class="fuel-form-overlay" role="dialog" aria-modal="true" :aria-label="title"><form ref="formRef" class="fuel-form-card" data-kfe-draft-form="true" data-kfe-form-architecture="universal" data-form-type="default" :data-kfe-draft-key="draftKey" @submit.prevent="save">
<header class="fuel-form-header"><div><p class="fuel-eyebrow">KFE 2.0 · FUEL</p><h2>{{title}}</h2></div><button type="button" class="kfe-qf-close" :disabled="busy" aria-label="Close Quick Fuel" @click="closeOverlay">×</button></header>
<section v-if="!isEdit && latestFuel" class="last-fuel-entry" aria-label="Last fuel entry"><div><p class="fuel-eyebrow">LAST FUEL ENTRY</p><strong>{{Number(loadingLatestQuantity||0).toFixed(3)}} kg</strong><span> · ₹{{Number(latestFuel.amount_paise||0)/100}} · ₹{{Number(latestFuel.price_per_kg||0).toFixed(2)}}/kg</span></div><div class="last-fuel-meta">Odometer {{latestFuel.odometer}} · {{latestTimestampLabel}}<span v-if="latestFuel.location_name"> · {{latestFuel.location_name}}</span></div><button type="button" class="secondary-action" :disabled="busy" @click="startEditLatest">Edit</button></section>
<p v-else-if="!isEdit && !loadingLatest" class="last-fuel-empty">No previous fuel entry.</p><p class="fuel-form-help">Date/time and optional location are captured automatically without blocking the save.</p>
<label data-kfe-field data-label="Odometer"><span class="fuel-floating-label">Odometer *</span><input v-model="draft.odometer" inputmode="numeric" type="number" min="0" step="1" required autocomplete="off"></label>
<label data-kfe-field data-label="Price per kg"><span class="fuel-floating-label">Price per kg *</span><input v-model="draft.pricePerKg" inputmode="decimal" type="number" min="0" step="0.01" required autocomplete="off"></label>
<label data-kfe-field data-label="Amount"><span class="fuel-floating-label">Amount *</span><input v-model="draft.amount" inputmode="decimal" type="number" min="0" step="0.01" required autocomplete="off"></label>
<div class="fuel-calculated"><span>Refuelled kg</span><strong>{{quantityKg==null?'—':quantityKg.toFixed(3)+' kg'}}</strong></div><div class="fuel-meta"><span>🕒 {{timestampLabel}}</span><span>📍 {{locationLabel}}</span><small>{{gpsStatus}}</small></div><p v-if="error" class="kfe-qf-error" role="alert">{{error}}</p><p v-if="success" class="kfe-qf-success" role="status">✓ {{success}}</p>
<div class="fuel-actions"><button type="button" class="secondary-action" :disabled="busy" @click="cancel">Cancel</button><div class="kfe-qf-swipe-track" :aria-disabled="busy||!!success" aria-label="Save Quick Fuel"><span>{{busy?'Saving…':isEdit?'Save correction':'Save Fuel →'}}</span></div></div>
</form></div>
</template>
<style scoped>
.fuel-form-overlay{position:fixed;inset:0;z-index:2000;display:grid;place-items:center;padding:max(12px,env(safe-area-inset-top)) max(12px,env(safe-area-inset-right)) calc(112px + env(safe-area-inset-bottom) + var(--kfe-keyboard-inset,0px)) max(12px,env(safe-area-inset-left));background:rgba(0,0,0,.58);backdrop-filter:blur(12px);overflow:auto}.fuel-form-card{width:min(34rem,100%);max-height:min(92dvh,100%);overflow:auto;box-sizing:border-box;padding:18px;border:1px solid var(--kfe-ui-border,#303640);border-radius:22px;background:var(--kfe-ui-surface,#101419);color:var(--kfe-ui-text,#f7f9fb);box-shadow:0 20px 60px rgba(0,0,0,.4)}.fuel-form-header{display:flex;justify-content:space-between;align-items:flex-start;gap:1rem}.fuel-form-header h2{margin:.2rem 0 1rem}.fuel-eyebrow{margin:0;font-size:.75rem;font-weight:800;letter-spacing:.08em;color:var(--kfe-accent,#5ee6a8)}.kfe-qf-close{width:44px;height:44px;border:1px solid var(--kfe-ui-border,#303640);border-radius:12px;background:var(--kfe-ui-bg,#080a0d);color:inherit;font-size:1.5rem;line-height:1}.fuel-form-help{font-size:.78rem;color:var(--kfe-ui-muted,#a5adba)}.last-fuel-entry{display:grid;gap:.35rem;margin:0 0 1rem;padding:.85rem;border:1px solid var(--kfe-ui-border,#303640);border-radius:14px;background:var(--kfe-ui-bg,#080a0d)}.last-fuel-entry strong{font-size:1.15rem}.last-fuel-meta,.last-fuel-empty{font-size:.75rem;color:var(--kfe-ui-muted,#a5adba)}.fuel-form-card label{position:relative;display:grid;gap:5px;margin:14px 0;padding:10px 11px 8px;border:1px solid var(--kfe-ui-border,#303640);border-radius:16px;background:var(--kfe-ui-bg,#080a0d);min-height:78px}.fuel-floating-label{position:absolute;left:12px;top:7px;font-size:.67rem;font-weight:850;color:var(--kfe-ui-muted,#a5adba);pointer-events:none}.fuel-form-card input{width:100%;box-sizing:border-box;min-height:52px;margin-top:15px;padding:10px 11px;border:0;border-radius:10px;background:transparent;color:inherit;font-size:18px;outline:none}.fuel-form-card label:focus-within{border-color:var(--kfe-accent,#5ee6a8);box-shadow:0 0 0 3px color-mix(in srgb,var(--kfe-accent,#5ee6a8) 18%,transparent)}.fuel-calculated,.fuel-meta{display:flex;justify-content:space-between;gap:.75rem;align-items:center;padding:.8rem 0;border-top:1px solid var(--kfe-ui-border,#303640)}.fuel-meta{flex-wrap:wrap;font-size:.78rem;color:var(--kfe-ui-muted,#a5adba)}.fuel-meta small{width:100%;opacity:.85}.kfe-qf-error{padding:.7rem;border-radius:10px;background:#4b1717;color:#ffd6d6}.kfe-qf-success{padding:.8rem;border-radius:10px;background:#123d24;color:#c8f7d7;font-weight:800}.fuel-actions{display:flex;align-items:center;justify-content:flex-end;gap:.7rem;margin-top:1rem}.secondary-action{min-height:52px;padding:.72rem 1rem;border-radius:12px;border:1px solid var(--kfe-ui-border,#303640);background:var(--kfe-ui-bg,#080a0d);color:inherit}.kfe-qf-swipe-track{min-width:11rem;min-height:52px;padding:.8rem 1rem;display:grid;place-items:center;border-radius:999px;border:1px solid var(--kfe-accent,#5ee6a8);background:var(--kfe-accent,#5ee6a8);color:#07130c;font-weight:900;user-select:none}.kfe-qf-swipe-track[aria-disabled="true"]{opacity:.55}
</style>
